PixelChannels **allocate_pixel_channels(const Image *images) {
    int max_threads = get_max_threads();
    PixelChannels **channels = (PixelChannels **)malloc(max_threads * sizeof(PixelChannels *));
    if (channels == NULL) {
        return NULL;
    }

    int max_cols = get_max_columns(images);
    for (int i = 0; i < max_threads; i++) {
        channels[i] = (PixelChannels *)malloc(max_cols * sizeof(PixelChannels));
        if (channels[i] == NULL) {
            // Clean up previously allocated memory
            for (int j = 0; j < i; j++) {
                free(channels[j]);
            }
            free(channels);
            return NULL;
        }
        for (int j = 0; j < max_cols; j++) {
            channels[i][j] = 0;
        }
    }

    return channels;
}

