#include <stdlib.h>

PixelChannels **allocate_pixel_channel_arrays(const Image *images) {
    int max_threads = get_max_threads();
    PixelChannels **pixel_channels = (PixelChannels **)malloc(max_threads * sizeof(PixelChannels *));
    if (!pixel_channels) {
        return NULL;
    }

    int max_cols = get_max_columns(images);
    for (int i = 0; i < max_threads; i++) {
        pixel_channels[i] = (PixelChannels *)malloc(max_cols * sizeof(PixelChannels));
        if (!pixel_channels[i]) {
            // Clean up previously allocated memory
            for (int j = 0; j < i; j++) {
                free(pixel_channels[j]);
            }
            free(pixel_channels);
            return NULL;
        }

        // Initialize to zero
        for (int j = 0; j < max_cols; j++) {
            pixel_channels[i][j] = 0;
        }
    }

    return pixel_channels;
}
